const business = function contentPrompt({ body }) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) throw new Error('Request body must be an object');
  for (const field of ['topic', 'type', 'language', 'tone']) {
    if (body[field] != null && typeof body[field] !== 'string') throw new Error(field + ' must be a string');
  }
  const topic = body.topic || 'AI automation trends';
  const contentType = ['blog', 'newsletter', 'social'].includes(body.type) ? body.type : 'blog';
  const language = body.language || 'English';
  const tone = body.tone || 'professional but approachable';
  const prompts = {
    blog: `Write a complete blog post about: "${topic}"

Requirements:
- Title (H1)
- Introduction (2-3 sentences)
- 3 main sections with H2 headers
- Practical examples in each section
- Conclusion with call to action
- Tone: ${tone}
- Language: ${language}
- Length: ~600 words`,
    newsletter: `Write a newsletter issue about: "${topic}"

Requirements:
- Catchy subject line
- Opening hook (1-2 sentences)
- 3 key insights with brief explanations
- One actionable tip
- Sign-off
- Tone: ${tone}
- Language: ${language}
- Length: ~300 words`,
    social: `Write 3 social media posts about: "${topic}"

For each post:
- Platform variant (Twitter/X, LinkedIn, Instagram)
- Different angle for each
- Relevant hashtags
- Tone: ${tone}
- Language: ${language}`,
  };
  return { topic, contentType, language, prompt: prompts[contentType] };
}

return $input.all().map((item, index) => { const result = business({body:item.json.body}); return {json: result, pairedItem: {item: index}}; });

const business = function contentResult({ topic, contentType, content }) {
  if (typeof content !== 'string' || !content.trim()) throw new Error('The model returned no content');
  const escape = (text) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const displayTopic = escape(topic.slice(0, 200));
  return {
    text: `✍️ New content generated for topic: *${displayTopic}*`,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: `✍️ *Content Ready*\nTopic: ${displayTopic}\nType: ${contentType}` } },
      { type: 'section', text: { type: 'mrkdwn', text: escape(content.slice(0, 500)) + '...' } },
    ],
    response: { status: 'success', topic, contentType, content },
  };
}

return $input.all().map((item, index) => { const result = business({topic:$('Build Prompt').itemMatching(index).json.topic,contentType:$('Build Prompt').itemMatching(index).json.contentType,content:item.json.content?.[0]?.text}); return {json: result, pairedItem: {item: index}}; });
